// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface LabourFieldOut {
  field_id: number;
  code: string;
  label: string;
  section: "Admission" | "Delivery" | "Mother" | "Baby" | "Discharge";
  kind: "Text" | "Number" | "Choice" | "MultiChoice" | "YesNo" | "Date";
  choices: string[];
  unit: string | null;
  min_value: number | null;
  max_value: number | null;
  required: boolean;
  /** Required only when this column has when_value */
  when_code: string | null;
  when_value: string | null;
  /** Where a default column comes from (the Punjab HMIS manual's page, a PHC manual); null for the hospital's own */
  source: string | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

/** A delivery into the hospital's labour register, as a draft. */
export interface LabourEntryIn {
  /** The mother's admission (the mother is its patient) */
  admission_id: number;
  delivered_at: string;
  /** The employee who attended the delivery */
  attended_by: number;
  /** Column code -> value: Number a number, YesNo "Yes"/"No", Choice one of its choices, MultiChoice a list of them, Date YYYY-MM-DD */
  field_values?: Record<string, string | number | string[] | null>;
  babies: LabourBabyIn[];
}

export interface LabourBabyIn {
  /** 1 for a single birth; 1, 2 ... for twins and more */
  baby_no: number;
  /** A baby born alive: its own record (POST /maternity/newborns), a newborn of this mother; null for a stillbirth */
  newborn_patient_id?: number | null;
  /** Column code -> value, the Baby columns */
  field_values?: Record<string, string | number | string[] | null>;
}

export interface LabourEntryOut {
  entry_id: number;
  /** LR-YYYY-NNNNN */
  entry_number: string;
  /** The mother */
  patient_id: number;
  mrn: string;
  mother_name: string;
  admission_id: number;
  admission_number: string;
  delivered_at: string;
  attended_by: number;
  attended_by_name: string;
  /** Column code -> value (the sections other than Baby) */
  field_values: Record<string, string | number | string[]>;
  babies: LabourBabyOut[];
  /** Draft (editable) or Signed (never changes) */
  status: "Draft" | "Signed";
  /** Signed: the column labels as they were when it was signed */
  labels: Record<string, string> | null;
  recorded_at: string;
  signed_at: string | null;
  /** The signer's stamp (MSDS IMS 147) */
  author_stamp: AuthorStampOut | null;
  row_version: number;
}

export interface LabourBabyOut {
  baby_no: number;
  newborn_patient_id: number | null;
  field_values: Record<string, string | number | string[]>;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** A draft entry: the values sent change (null clears one); babies sent replace the babies. */
export interface LabourEntryPatch {
  delivered_at?: string | null;
  attended_by?: number | null;
  field_values?: Record<string, string | number | string[] | null> | null;
  babies?: LabourBabyIn[] | null;
  /** row_version as read */
  expected_version: number;
}

/** A baby born to a mother admitted here: a patient of its own, 'Baby of' the mother, with its own band. */
export interface NewbornIn {
  /** The mother's current admission */
  admission_id: number;
  born_at: string;
  gender: "male" | "female" | "other" | "unknown";
}

export interface NewbornRegisteredOut {
  patient_id: number;
  mrn: string;
  /** 'Baby of' the mother until the family names the baby (the patient's record) */
  full_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  born_at: string;
  mother_patient_id: number;
  mother_mrn: string;
  mother_name: string;
  birth_admission_id: number;
  admission_number: string;
  /** The baby's own band on the mother's admission, ready to print */
  wristband: WristbandIssuedOut;
}

export interface WristbandIssuedOut {
  wristband: WristbandOut;
  print: PrintOut_WristbandFieldsOut_;
}

export interface WristbandOut {
  wristband_id: number;
  patient_id: number;
  admission_id: number | null;
  er_visit_id: number | null;
  reason: "Admission" | "Emergency" | "Newborn" | "Replacement";
  replacement_reason: string | null;
  issued_by: number;
  issued_by_name: string;
  issued_at: string;
  replaced_at: string | null;
  /** The band the patient wears now */
  is_current: boolean;
  row_version: number;
  patient_name: string;
  mrn: string;
  admission_number: string | null;
  er_number: string | null;
}

export interface PrintOut_WristbandFieldsOut_ {
  document_type: "autopsy_order" | "bed_labels" | "blood_component_label" | "blood_donation_labels" | "clinical_note" | "complaint_letter" | "complaints_notice" | "consent_form" | "cost_estimate" | "cssd_labels" | "death_certificate" | "discharge_summary" | "dispensing_label" | "dose_label" | "id_card" | "imaging_report" | "lab_label" | "lab_report" | "mlc_intimation" | "opd_slip" | "pharmacy_receipt" | "prescription" | "referral_slip" | "send_out_manifest" | "surgical_record" | "triage_algorithm" | "wristband";
  /** Which printer of the terminal to use (GET /api/v1/terminals/whoami) */
  printer_role: "receipt" | "label" | "document" | "card";
  paper_width_mm: number;
  /** The document's data, for frontends that render their own layout */
  fields: WristbandFieldsOut;
  /** Pre-formatted monospace text (48 columns) for ESC/POS printers, as is */
  text: string | null;
  barcode_svg: string | null;
  qr_svg: string | null;
  pdf_url: string | null;
}

/** What the band shows (print it on the wristband printer, mapped as the terminal's label printer). */
export interface WristbandFieldsOut {
  wristband_id: number;
  hospital_name: string;
  patient_name: string;
  father_or_husband_name: string | null;
  /** Also the barcode; the QR code reads HMS:PT:<mrn> */
  mrn: string;
  gender: string | null;
  /** e.g. 34y, 8m, 5d */
  age: string | null;
  dob: string | null;
  admission_number: string | null;
  er_number: string | null;
  ward_name: string | null;
  bed_label: string | null;
  /** Print prominently (a red band or a red mark) when set */
  allergies: string | null;
  blood_group: string | null;
  issued_at: string;
}

export interface NewbornOut {
  patient_id: number;
  mrn: string;
  /** 'Baby of' the mother until the family names the baby (the patient's record) */
  full_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  born_at: string;
  mother_patient_id: number;
  mother_mrn: string;
  mother_name: string;
  birth_admission_id: number;
  admission_number: string;
}

/** The labour register's columns, in order — GET /api/v1/maternity/labour-register/columns (who may call: holders of maternity.view or maternity.record or maternity.policy.manage). */
export function listColumns(query?: { include_inactive?: boolean }): Promise<LabourFieldOut[]> {
  return api<LabourFieldOut[]>("GET", withQuery(`/maternity/labour-register/columns`, query), undefined);
}

/** Record a delivery in the labour register (a draft) — POST /api/v1/maternity/labour-register (who may call: holders of maternity.record). */
export function createEntry(body: LabourEntryIn): Promise<LabourEntryOut> {
  return api<LabourEntryOut>("POST", `/maternity/labour-register`, body, { idempotent: true });
}

/** Deliveries of a period, newest first — GET /api/v1/maternity/labour-register (who may call: holders of maternity.view). */
export function listEntriesMaternityLabourRegister(query: { date_from: string; date_to: string; status?: "Draft" | "Signed" | null; limit?: number }): Promise<LabourEntryOut[]> {
  return api<LabourEntryOut[]>("GET", withQuery(`/maternity/labour-register`, query), undefined);
}

/** One delivery of the labour register — GET /api/v1/maternity/labour-register/{entry_id} (who may call: holders of maternity.view or maternity.record). */
export function getEntry(entry_id: number): Promise<LabourEntryOut> {
  return api<LabourEntryOut>("GET", `/maternity/labour-register/${entry_id}`, undefined);
}

/** Complete or correct a draft entry — PATCH /api/v1/maternity/labour-register/{entry_id} (who may call: holders of maternity.record). */
export function updateEntryMaternityLabourRegister(entry_id: number, body: LabourEntryPatch): Promise<LabourEntryOut> {
  return api<LabourEntryOut>("PATCH", `/maternity/labour-register/${entry_id}`, body);
}

/** Sign an entry of the labour register — POST /api/v1/maternity/labour-register/{entry_id}/sign (who may call: holders of maternity.record). */
export function signEntry(entry_id: number): Promise<LabourEntryOut> {
  return api<LabourEntryOut>("POST", `/maternity/labour-register/${entry_id}/sign`, undefined);
}

/** A baby's birth notification for the union council (PDF) — GET /api/v1/maternity/labour-register/{entry_id}/babies/{baby_no}/birth-notification/pdf (who may call: holders of maternity.record or maternity.view). */
export function birthNotification(entry_id: number, baby_no: number): Promise<unknown> {
  return api<unknown>("GET", `/maternity/labour-register/${entry_id}/babies/${baby_no}/birth-notification/pdf`, undefined);
}

/** Register a newborn and print its band — POST /api/v1/maternity/newborns (who may call: holders of maternity.record and patient.wristband.print). */
export function registerNewborn(body: NewbornIn): Promise<NewbornRegisteredOut> {
  return api<NewbornRegisteredOut>("POST", `/maternity/newborns`, body, { idempotent: true });
}

/** Newborns of a mother or a period — GET /api/v1/maternity/newborns (who may call: holders of maternity.view). */
export function newborns(query?: { mother_patient_id?: number | null; date_from?: string | null; date_to?: string | null; limit?: number; before_id?: number | null }): Promise<NewbornOut[]> {
  return api<NewbornOut[]>("GET", withQuery(`/maternity/newborns`, query), undefined);
}
